// Objects start in Gen 0
var obj = new LargeObject(); // Gen 0

// If obj survives collection, it moves to Gen 1
// If it survives again, it moves to Gen 2

// Best practices:
// 1. Don't allocate large objects (>85K) frequently - they go directly to LOH (Large Object Heap)
// 2. Use ArrayPool<T> for temporary large arrays
// 3. Implement IDisposable for unmanaged resources
// 4. Avoid GC.Collect() unless absolutely necessary

// Checking generation
var generation = GC.GetGeneration(obj);
Console.WriteLine($"Object is in generation: {generation}");

// Forcing collection (rarely needed)
GC.Collect();
GC.WaitForPendingFinalizers();
GC.Collect();
